 "content": "from collections import deque


def transform(grid):
    """Recolor each connected 1-shape to the color of an identical shape."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while queue:
                x, y = queue.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        queue.append((nx, ny))
            min_r = min(x for x, _ in cells)
            min_c = min(y for _, y in cells)
            shape = frozenset((x - min_r, y - min_c) for x, y in cells)
            components.append((color, cells, shape))

    shape_colors = {}
    for color, _, shape in components:
        if color != 1:
            shape_colors[shape] = color

    output = [row[:] for row in grid]
    for color, cells, shape in components:
        if color == 1 and shape in shape_colors:
            replacement = shape_colors[shape]
            for r, c in cells:
                output[r][c] = replacement
    return output
